  if (m === 0) return 0;
  const n = heightMap[0].length;
  if (m <= 2 || n <= 2) return 0;

  const visited = Array.from({ length: m }, () => Array(n).fill(false));

  class MinHeap {
    constructor() {
      this.data = [];
    }
    push(node) {
      this.data.push(node);
      this._siftUp(this.data.length - 1);
    }
    pop() {
      if (this.data.length === 0) return null;
      const top = this.data[0];
      const last = this.data.pop();
      if (this.data.length > 0) {
        this.data[0] = last;
        this._siftDown(0);
      }
      return top;
    }
    _siftUp(i) {
      const data = this.data;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (data[p].h <= data[i].h) break;
        [data[p], data[i]] = [data[i], data[p]];
        i = p;
      }
    }
    _siftDown(i) {
      const data = this.data;
      const n = data.length;
      while (true) {
        let l = i * 2 + 1;
        let r = l + 1;
        let smallest = i;
        if (l < n && data[l].h < data[smallest].h) smallest = l;
        if (r < n && data[r].h < data[smallest].h) smallest = r;
        if (smallest === i) break;
        [data[i], data[smallest]] = [data[smallest], data[i]];
        i = smallest;
      }
    }
  }

  const heap = new MinHeap();

  // Add all boundary cells to the heap
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 || i === m - 1 || j === 0 || j === n - 1) {
        heap.push({ h: heightMap[i][j], i, j });
        visited[i][j] = true;
      }
    }
  }

  const dirs = [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1],
  ];
  let water = 0;

  while (heap.data.length) {
    const cell = heap.pop();
    for (const [di, dj] of dirs) {
      const ni = cell.i + di;
      const nj = cell.j + dj;
      if (
        ni < 0 ||
        ni >= m ||
        nj < 0 ||
        nj >= n ||
        visited[ni][nj]
      )
        continue;
      visited[ni][nj] = true;
      const nh = heightMap[ni][nj];
      if (cell.h > nh) water += cell.h - nh;
      heap.push({ h: Math.max(nh, cell.h), i: ni, j: nj });
    }
  }

  return water;
}
